<script setup lang="ts">import{computed,ref}from'vue';import{useI18n}from'vue-i18n';import{boxes,cards,type BlindBox}from'../data';import DrawModal from'../components/DrawModal.vue';const{t,tm}=useI18n(),box:BlindBox=boxes[0],chosen=ref<BlindBox|null>(null),count=ref(1),cardKeys=['pikachu','gengar','mewtwo','eevee'];function draw(n:number){chosen.value=box;count.value=n}const tierNames=computed(()=>tm('detail.tiers') as string[]);const tiers=computed(()=>[{name:tierNames.value[0],chance:'1.00%',items:[0]},{name:tierNames.value[1],chance:'5.00%',items:[1,2]},{name:tierNames.value[2],chance:'14.00%',items:[2,1]}]);const rules=computed(()=>tm('detail.rules') as string[][]);const cardName=(index:number)=>t(`cards.${cardKeys[index]}.name`),cardTag=(index:number)=>t(`cards.${cardKeys[index]}.tag`)</script>
<template><main class="page detail-page"><div class="container"><nav class="crumb"><RouterLink to="/blind-boxes">{{t('detail.breadcrumb')}}</RouterLink> / {{t(`boxes.${box.id}.name`)}}</nav><section class="product-hero"><div class="gallery card"><img :src="box.image" :alt="t(`boxes.${box.id}.name`)"><div class="thumbs"><button><img :src="box.image" :alt="t(`boxes.${box.id}.name`)"></button><button><img :src="cards[0].image" :alt="cardName(0)"></button><button><img :src="cards[1].image" :alt="cardName(1)"></button></div></div><div class="product-info"><div class="tags"><span class="pill gold">{{t('detail.licensed')}}</span><span class="pill red">{{t('detail.hot')}}</span><span class="pill">{{t('detail.pikachu')}}</span></div><h1>{{t(`boxes.${box.id}.name`)}}</h1><p class="muted">{{t('detail.description')}}</p><div class="pricing card"><div><small>{{t('detail.single')}}</small><b>{{box.price}} <em>OK Coin</em></b></div><div><small>{{t('detail.ten')}}</small><b>{{box.price*10|0}} <em>OK Coin</em></b></div></div><div class="balance"><span>{{t('detail.balance')}} <b>12,450 OK Coin</b></span><RouterLink to="/recharge">+</RouterLink></div><div class="inventory"><div><span>{{t('detail.stock')}}</span><b>{{box.remaining}} / {{box.total}} ({{box.remaining}}%)</b></div><div class="progress"><i :style="{width:`${box.remaining}%`}"></i></div><small>{{t('detail.updated')}}</small></div><div class="cta"><button class="btn btn-outline" @click="draw(1)">{{t('detail.single')}}</button><button class="btn btn-primary" @click="draw(10)">{{t('detail.ten')}}</button></div><div class="rule-alert">ⓘ {{t('detail.ruleAlert')}}</div></div></section><section class="pool"><div class="pool-head"><div><span class="eyebrow">{{t('eyebrow.prizePool')}}</span><h2 class="section-title">{{t('detail.pool')}}</h2></div><p>{{t('detail.poolHint')}}</p></div><div v-for="(tier,tierIndex) in tiers" :key="tier.name" class="tier"><div class="tier-title"><span>{{tier.name}}</span><b>{{t('detail.tierChance',{chance:tier.chance})}}</b></div><div class="card-pool"><article v-for="(cardIndex,itemIndex) in tier.items" :key="`${tierIndex}-${cardIndex}-${itemIndex}`" class="prize card"><div class="prize-img"><img :src="cards[cardIndex].image" :alt="cardName(cardIndex)"><span v-if="itemIndex===1&&tierIndex===2">{{t('detail.sold')}}</span></div><h3>{{cardName(cardIndex)}}</h3><div class="prize-tags"><span class="pill">{{cardTag(cardIndex)}}</span><span class="pill gold">{{t('detail.recyclable',{coin:cards[cardIndex].coin})}}</span></div><dl><div><dt>{{t('detail.initial')}}</dt><dd>{{tierIndex===0?1:5}}</dd></div><div><dt>{{t('detail.stock')}}</dt><dd>{{itemIndex===1&&tierIndex===2?0:tierIndex===0?1:3}}</dd></div><div><dt>{{t('detail.live')}}</dt><dd>{{itemIndex===1&&tierIndex===2?'0%':tier.chance}}</dd></div></dl></article></div></div><div class="template-reward"><div class="template-art"><img src="/images/pokemon/pikachu.png" :alt="t('detail.pikachu')"></div><div><span class="pill gold">{{t('detail.guarantee')}}</span><h3>{{t('detail.randomCard')}}</h3><p>{{t('detail.randomHint')}}</p></div><dl><div><dt>{{t('detail.recyclable',{coin:''})}}</dt><dd>100 Coin</dd></div><div><dt>{{t('detail.slots')}}</dt><dd>28 / 50</dd></div><div><dt>{{t('detail.live')}}</dt><dd>73.68%</dd></div></dl></div></section><section class="rules"><article v-for="rule in rules" :key="rule[0]"><h3>{{rule[0]}}</h3><p>{{rule[1]}}</p></article></section></div><div class="mobile-buy mobile-only"><span><b>{{box.price}}</b> OK Coin</span><button class="btn btn-primary" @click="draw(1)">{{t('detail.drawNow')}}</button></div><DrawModal :box="chosen" :count="count" @close="chosen=null"/></main></template>
<style scoped>.crumb{font-size:12px;color:var(--muted);margin-bottom:26px}.product-hero{display:grid;grid-template-columns:1fr 1fr;gap:52px}.gallery{padding:28px;background:linear-gradient(145deg,#fff8bd,#d8ecff)}.gallery>img{width:100%;height:460px;padding:24px;object-fit:contain;filter:drop-shadow(0 20px 18px rgba(65,50,5,.2));border-radius:12px}.thumbs{display:flex;gap:10px;margin-top:12px}.thumbs button{width:62px;height:62px;padding:3px;background:#fff;border:1px solid var(--line);border-radius:8px}.thumbs img{width:100%;height:100%;padding:4px;object-fit:contain;background:#fff8d6}.product-info h1{font-size:38px;line-height:1.2;margin:16px 0}.tags{display:flex;gap:8px}.pricing{display:grid;grid-template-columns:1fr 1fr;padding:20px;margin:26px 0}.pricing div+div{border-left:1px solid var(--line);padding-left:25px}.pricing small{display:block;color:var(--muted)}.pricing b{display:block;font-size:26px;color:var(--brown);margin-top:6px}.pricing em{font-size:11px;font-style:normal}.balance,.inventory>div:first-child{display:flex;justify-content:space-between}.balance a{width:26px;height:26px;border-radius:50%;background:var(--gold);display:grid;place-items:center;font-weight:900}.inventory{margin:25px 0}.inventory>div:first-child{font-size:13px;margin-bottom:8px}.inventory small{display:block;text-align:right;color:var(--muted);margin-top:7px}.cta{display:grid;grid-template-columns:1fr 1fr;gap:12px}.rule-alert{font-size:12px;color:#615516;background:#fff9d7;border-radius:8px;padding:12px;margin-top:16px}.pool{margin-top:90px}.pool-head{display:flex;justify-content:space-between;align-items:end;border-bottom:1px solid var(--line);padding-bottom:20px}.pool-head p{font-size:12px;color:var(--muted)}.tier{margin:38px 0}.tier-title{display:flex;align-items:center;gap:12px;margin-bottom:15px}.tier-title span{background:var(--brown);color:#fff;border-radius:20px;padding:6px 12px;font-size:12px;font-weight:700}.tier-title b{font-size:12px;color:var(--muted)}.card-pool{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.prize{padding:14px}.prize-img{aspect-ratio:3/4;background:radial-gradient(circle,#fff 0 18%,transparent 55%),linear-gradient(145deg,#fff4a6,#badcff);border-radius:9px;overflow:hidden;position:relative}.prize-img img{width:100%;height:100%;padding:18px;object-fit:contain;filter:drop-shadow(0 12px 12px rgba(45,38,10,.18))}.prize-img>span{position:absolute;inset:0;background:rgba(0,0,0,.58);color:#fff;display:grid;place-items:center;font-weight:800}.prize h3{font-size:14px}.prize-tags{display:flex;gap:5px;flex-wrap:wrap}.prize dl,.template-reward dl{display:grid;grid-template-columns:repeat(3,1fr);margin:14px 0 0}.prize dl div,.template-reward dl div{text-align:center}.prize dt,.template-reward dt{font-size:10px;color:var(--muted)}.prize dd,.template-reward dd{font-size:12px;font-weight:700;margin:4px 0}.template-reward{display:grid;grid-template-columns:130px 1fr 1fr;gap:28px;align-items:center;background:#fffbea;border:1px solid #f0df70;border-radius:18px;padding:24px}.template-art{height:170px;border-radius:12px;background:linear-gradient(145deg,#fff5a6,#ffd43b);display:grid;place-items:center;overflow:hidden}.template-art img{width:100%;height:100%;padding:16px;object-fit:contain;filter:drop-shadow(0 12px 10px rgba(70,50,0,.18))}.template-reward p{font-size:13px;color:var(--muted)}.rules{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-top:45px}.rules article{padding:18px;border-top:2px solid var(--gold)}.rules p{font-size:12px;color:var(--muted);line-height:1.7}@media(max-width:900px){.product-hero{grid-template-columns:1fr}.card-pool{grid-template-columns:repeat(2,1fr)}.template-reward{grid-template-columns:110px 1fr}.template-reward dl{grid-column:1/-1}.rules{grid-template-columns:1fr 1fr}}@media(max-width:600px){.gallery>img{height:330px}.product-info h1{font-size:30px}.pool-head{display:block}.card-pool{grid-template-columns:1fr 1fr;gap:10px}.template-reward{grid-template-columns:90px 1fr;padding:15px;gap:14px}.rules{grid-template-columns:1fr}}</style>
